"use client";

import * as React from "react"
import { siGithub } from "simple-icons"

import { BotIcon, MenuIcon, SearchIcon } from "@/components/icons"
import { Badge } from "@/registry/base-nova/ui/badge"
import { BrandIcon } from "@/registry/base-nova/ui/brand-icon"
import { Button } from "@/registry/base-nova/ui/button"
import { IconChip } from "@/registry/base-nova/ui/icon-chip"
import { Kbd } from "@/registry/base-nova/ui/kbd"
import { NavigationMenu, NavigationMenuItem, NavigationMenuLink, NavigationMenuList } from "@/registry/base-nova/ui/navigation-menu"
import { ThemeToggle } from "@/registry/base-nova/ui/theme-toggle"

import { SECTIONS } from "./site"

/** Opens the search palette and the navigation drawer; provided once by DocsTemplate. */
export const DocsChromeContext = React.createContext<{ openSearch: () => void; openNav: () => void }>({
  openSearch: () => {},
  openNav: () => {},
})
export const useDocsChrome = () => React.useContext(DocsChromeContext)

export function Brand() {
  return (
    <a href="#" className="flex shrink-0 items-center gap-2.5 rounded-full font-semibold outline-none focus-visible:ring-2 focus-visible:ring-ring/50">
      <IconChip size="sm" tone="solid">
        <BotIcon />
      </IconChip>
      <span>
        Tessel <span className="font-normal text-muted-foreground">Docs</span>
      </span>
    </a>
  )
}

/** Search field on wide screens, an icon button on phones. `compact` keeps it an icon at every width. */
export function SearchButton({ compact }: { compact?: boolean }) {
  const { openSearch } = useDocsChrome()
  if (compact)
    return (
      <Button variant="ghost" size="icon-sm" onClick={openSearch} aria-label="Search docs" aria-keyshortcuts="Meta+K">
        <SearchIcon />
      </Button>
    )
  return (
    <Button
      variant="secondary"
      size="sm"
      onClick={openSearch}
      aria-label="Search docs"
      aria-keyshortcuts="Meta+K"
      className="w-8 px-0 text-muted-foreground sm:w-64 sm:justify-start sm:px-3"
    >
      <SearchIcon />
      <span className="hidden sm:inline">Search docs…</span>
      <Kbd className="ms-auto max-sm:hidden">⌘K</Kbd>
    </Button>
  )
}

export function HeaderActions({ compactSearch }: { compactSearch?: boolean }) {
  return (
    <div className="ms-auto flex items-center gap-1.5">
      <SearchButton compact={compactSearch} />
      <Button variant="ghost" size="icon-sm" nativeButton={false} render={<a href="#" />} aria-label="GitHub">
        <BrandIcon icon={siGithub} />
      </Button>
      <ThemeToggle variant="ghost" modes="tri" />
    </div>
  )
}

/** Section links as header tabs: the current section has the bar. */
export function SectionTabs({ current, className }: { current?: string; className?: string }) {
  return (
    <NavigationMenu aria-label="Sections" className={className}>
      <NavigationMenuList className="h-full items-stretch gap-1">
        {SECTIONS.map((s) => (
          <NavigationMenuItem key={s.id}>
            <NavigationMenuLink variant="tab" href="#" active={s.id === current} aria-current={s.id === current ? "page" : undefined}>
              {s.title}
            </NavigationMenuLink>
          </NavigationMenuItem>
        ))}
      </NavigationMenuList>
    </NavigationMenu>
  )
}

/**
 * The top bar. `menu` adds the button that opens the navigation drawer (`lg:hidden` by default,
 * `always` on layouts without a sidebar); `children` sit between the brand and the actions.
 */
export function DocsHeader({
  menu = "narrow",
  version = true,
  compactSearch,
  children,
  below,
}: {
  menu?: "narrow" | "always" | "none"
  version?: boolean
  compactSearch?: boolean
  children?: React.ReactNode
  /** A second row under the bar (section tabs). */
  below?: React.ReactNode
}) {
  const { openNav } = useDocsChrome()
  return (
    <header className="sticky top-0 z-40 shrink-0 border-b border-border bg-background">
      <div className="flex h-14 items-center gap-3 px-3 sm:px-4">
        {menu !== "none" && (
          <Button variant="ghost" size="icon-sm" className={menu === "narrow" ? "lg:hidden" : undefined} aria-label="Open navigation" onClick={openNav}>
            <MenuIcon />
          </Button>
        )}
        <Brand />
        {version && (
          <Badge size="sm" variant="outline" className="max-sm:hidden">
            v2.4
          </Badge>
        )}
        {children}
        <HeaderActions compactSearch={compactSearch} />
      </div>
      {below}
    </header>
  )
}

"use client";

import {
  SidebarNav,
  SidebarNavContent,
  SidebarNavLink,
  SidebarNavList,
  SidebarNavSection,
} from "@/registry/base-nova/ui/sidebar-nav"
import { Badge } from "@/registry/base-nova/ui/badge"

import { CURRENT_PAGE, SECTIONS } from "./site"

/**
 * The page tree. `section` limits it to one section's groups (the Notebook layout shows the
 * other sections as header tabs); without it every section is a collapsible heading.
 */
export function DocsNav({ section, className }: { section?: string; className?: string }) {
  const sections = section ? SECTIONS.filter((s) => s.id === section) : SECTIONS
  return (
    <SidebarNav className={className}>
      <SidebarNavContent aria-label="Docs" className="pt-3">
        {sections.map((s) =>
          section ? (
            s.groups.map((g) => <Group key={g.label} label={g.label} pages={g.pages} level="section" />)
          ) : (
            <SidebarNavSection key={s.id} label={s.title}>
              {s.groups.map((g) => (
                <Group key={g.label} label={g.label} pages={g.pages} level="group" />
              ))}
            </SidebarNavSection>
          ),
        )}
      </SidebarNavContent>
    </SidebarNav>
  )
}

function Group({ label, pages, level }: { label: string; pages: { title: string; href: string; badge?: string }[]; level: "section" | "group" }) {
  return (
    <SidebarNavSection label={label} level={level} collapsible={level === "group"}>
      <SidebarNavList>
        {pages.map((p) => (
          <SidebarNavLink
            key={p.title}
            href={p.href}
            active={p.title === CURRENT_PAGE}
            badge={
              p.badge ? (
                <Badge variant="success" size="sm">
                  {p.badge}
                </Badge>
              ) : undefined
            }
          >
            {p.title}
          </SidebarNavLink>
        ))}
      </SidebarNavList>
    </SidebarNavSection>
  )
}

import type * as React from "react"

import { BoltIcon, LightbulbIcon, HomeIcon, KeyIcon, ServerIcon, ShieldIcon, TerminalSquareIcon } from "@/components/icons"
import type { CommandPaletteItem } from "@/registry/base-nova/blocks/command-palette/command-palette"

/** Site content shared by every layout: sections (header tabs), their nav groups, search and the pager. */

export type NavPage = { title: string; href: string; badge?: string }
export type NavGroupData = { label: string; pages: NavPage[] }
export type SectionData = {
  id: string
  title: string
  description: string
  icon: React.ComponentType<{ className?: string }>
  groups: NavGroupData[]
}

const page = (title: string, badge?: string): NavPage => ({ title, href: "#", badge })

export const SECTIONS: SectionData[] = [
  {
    id: "guides",
    title: "Guides",
    description: "Set up Tessel and decide what it may do on its own.",
    icon: LightbulbIcon,
    groups: [
      { label: "Getting started", pages: [page("Introduction"), page("Quickstart"), page("Install the GitHub app")] },
      { label: "Safety", pages: [page("Approval policies"), page("Secrets"), page("Audit log", "New")] },
      { label: "Sandboxes", pages: [page("Images"), page("Network rules"), page("Caching")] },
    ],
  },
  {
    id: "reference",
    title: "Reference",
    description: "Every command, flag and setting in one place.",
    icon: TerminalSquareIcon,
    groups: [
      { label: "CLI", pages: [page("tessel run"), page("tessel approve"), page("tessel logs")] },
      { label: "Configuration", pages: [page("tessel.toml"), page("Environment")] },
    ],
  },
  {
    id: "api",
    title: "API",
    description: "Start sessions and read their results from your own tools.",
    icon: KeyIcon,
    groups: [{ label: "REST API", pages: [page("Authentication"), page("Sessions"), page("Webhooks")] }],
  },
  {
    id: "integrations",
    title: "Integrations",
    description: "Run Tessel from CI and the tools your team already uses.",
    icon: BoltIcon,
    groups: [{ label: "CI", pages: [page("GitHub Actions"), page("Buildkite")] }],
  },
]

export const CURRENT_SECTION = "guides"
export const CURRENT_PAGE = "Approval policies"

export const PAGER = {
  prev: { title: "Install the GitHub app", section: "Getting started" },
  next: { title: "Secrets", section: "Safety" },
}

export const SEARCH_ITEMS: CommandPaletteItem[] = [
  { id: "quickstart", label: "Quickstart", group: "Getting started", icon: HomeIcon },
  { id: "github", label: "Install the GitHub app", group: "Getting started", icon: HomeIcon },
  { id: "approvals", label: "Approval policies", group: "Guides", icon: ShieldIcon, keywords: ["allow", "deny", "risk"] },
  { id: "sandboxes", label: "Sandbox images", group: "Guides", icon: ServerIcon },
  { id: "ci", label: "Auto-fix GitHub Actions", group: "Integrations", icon: BoltIcon },
  { id: "run", label: "tessel run", group: "Reference", icon: TerminalSquareIcon, keywords: ["cli"] },
  { id: "auth", label: "API authentication", group: "API", icon: KeyIcon, keywords: ["token"] },
]

import { DocsTemplate } from "@/registry/base-nova/templates/docs/docs"

export default function DocsPage() {
  return <DocsTemplate />
}
